"use client";

import { useEffect, ReactNode } from "react";
import { useRouter, usePathname } from "next/navigation";
import { useAuthStore } from "../../store/auth.store"; // Ajusta ruta
import { MainLayout } from "../../components/layout/MainLayout"; // Ajusta ruta
import { QueryClient, QueryClientProvider } from "@tanstack/react-query"; // Para las páginas dentro de pwa_app
import { Center, Loader } from "@mantine/core";

// Crear una instancia de QueryClient para este layout y sus hijos
const pwaAppQueryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 1000 * 60 * 1, // 1 minuto
      refetchOnWindowFocus: false,
    },
  },
});

export default function PwaAppLayout({ children }: { children: ReactNode }) {
  const isAuthenticated = useAuthStore((state) => state.isAuthenticated);
  const user = useAuthStore((state) => state.user);
  const isLoadingAuth = useAuthStore((state) => state.isLoading); // Estado de carga del store
  const router = useRouter();
  const pathname = usePathname();

  useEffect(() => {
    // Dar tiempo a que el estado se hidrate desde localStorage
    if (isLoadingAuth) {
      return;
    }

    if (!isAuthenticated) {
      console.log("PwaAppLayout: Not authenticated, redirecting to /login");
      router.replace("/login"); // Redirige a la página de login PWA
      return;
    }

    // Si está autenticado pero no tiene país Y NO está en la página de set-country
    if (
      isAuthenticated &&
      user &&
      !user.countryOfOrigin &&
      pathname !== "/set-country"
    ) {
      console.log(
        "PwaAppLayout: Authenticated but no country, redirecting to /set-country"
      );
      router.replace("/set-country");
      return;
    }

    // Si está autenticado, tiene país Y está en la página de set-country, redirigir al dashboard
    if (
      isAuthenticated &&
      user &&
      user.countryOfOrigin &&
      pathname === "/set-country"
    ) {
      console.log(
        "PwaAppLayout: Authenticated with country on set-country page, redirecting to /dashboard"
      );
      router.replace("/dashboard");
    }
  }, [isAuthenticated, user, isLoadingAuth, router, pathname]);

  // Muestra un loader mientras se verifica la autenticación o si se está redirigiendo
  if (isLoadingAuth) {
    return (
      <Center style={{ height: "100vh" }}>
        <Loader />
      </Center>
    );
  }

  // Si no está autenticado, o si no tiene país y no es la página de set-country,
  // no renderizar el MainLayout para evitar un flash antes de la redirección.
  if (
    !isAuthenticated ||
    (user && !user.countryOfOrigin && pathname !== "/set-country")
  ) {
    return (
      <Center style={{ height: "100vh" }}>
        <Loader />
      </Center>
    ); // O un loader más específico
  }

  // Si todo está bien, renderiza el MainLayout con el contenido
  return (
    <QueryClientProvider client={pwaAppQueryClient}>
      {/* Provider para las páginas PWA */}
      <MainLayout navItems={pwaAppMenuItems}>
        {/* Pasa los items de menú PWA */}
        {children}
      </MainLayout>
    </QueryClientProvider>
  );
}

// Define pwaAppMenuItems (puedes moverlo a un archivo de config)
import {
  IconHome,
  IconPlus,
  IconHistory,
  IconShoppingCart,
  IconUserCircle,
  IconMapSearch,
} from "@tabler/icons-react";
import type { NavLinkItem } from "../../components/layout/MainLayout"; // Asume que NavLinkItem está en MainLayout

const pwaAppMenuItems: NavLinkItem[] = [
  { href: "/dashboard", label: "Inicio", icon: IconHome },
  { href: "/orders/new", label: "Nueva Resolución", icon: IconPlus },
  { href: "/orders", label: "Mi Historial", icon: IconHistory },
  { href: "/credits", label: "Comprar Créditos", icon: IconShoppingCart },
  // { href: '/profile', label: 'Mi Perfil', icon: IconUserCircle }, // Puedes añadir una página de perfil más adelante
  // { label: 'Mapa de Cobertura', icon: IconMapSearch, externalLink: 'URL_MAPA_PWA' }, // Si aplica
];
